/* Generated by `pnpm kit:gen` (packages/engine/scripts/kit-gen.ts): each field effect's kernel in C, in double
   precision, as kit/compile.ts writes it from kit/fields/<kind>.ts: edit those files, never this one. video.c includes
   it; kit.h declares what the kernels call, which the clips' module defines. */
#include "kit.h"

/* kit/fields/demo.ts: demoField, cost 112 */
static double kfield_demo(double x, double y, const double *U, const double *F) {
  double px = x;
  double py = y;
  for (int i = 0; i < 2; i++) {
    const double dx = U[4 * i];
    const double dy = U[4 * i + 1];
    const double s = kit_sin(U[4 * i + 2] * (dx * px + dy * py) + F[i]) * U[4 * i + 3];
    px -= dy * s;
    py += dx * s;
  }
  double f = 0.6 * px;
  for (int i = 0; i < 5; i++) {
    const double s = U[4 * i + 10] * (U[4 * i + 8] * px + U[4 * i + 9] * py) + F[i + 2];
    f += U[4 * i + 11] * kit_sin(s);
  }
  return f;
}

/* kit/fields/strata.ts: strataField, cost 151 */
static double kfield_strata(double x, double y, const double *U, const double *F) {
  const double w = kit_sin(U[2] * (U[0] * x + U[1] * y) + F[0]) * U[3];
  double px = x - U[1] * w;
  double py = y + U[0] * w;
  for (int i = 0; i < 2; i++) {
    const double sn = kit_sin(F[i + 1]);
    const double cx = U[7 * i + 4] + U[7 * i + 9] * kit_cos(F[i + 1]);
    const double cy = U[7 * i + 5] + U[7 * i + 10] * sn;
    const double vx = px - cx;
    const double vy = py - cy;
    const double t = (U[7 * i + 6] + U[7 * i + 7] * sn) / (1.0 + (vx * vx + vy * vy) * U[7 * i + 8]);
    const double t2 = t * t;
    const double n = 1.0 / (1.0 + t2);
    const double c = (1.0 - t2) * n;
    const double s = 2.0 * t * n;
    px = cx + c * vx - s * vy;
    py = cy + s * vx + c * vy;
  }
  const double s = U[18] * px + U[19] * py;
  const double r = U[23];
  const double b = U[21] * s + U[22] + F[3];
  return s + U[20] * kit_atan2(r * kit_sin(b), 1.0 - r * kit_cos(b));
}

/* every kernel, by its kind's place in kit/gen/kernel-order.ts */
static const kit_kernel KIT_KERNELS[] = {kfield_demo, kfield_strata};
